import numpy as np, itertools, sys
orbs=[(a,b) for a in range(5) for b in range(a+1)]  # 15 orbits, bit i of id
def orbit_pts(a,b):
    s=set()
    for p,q in [(a,b),(b,a)]:
        for sp in [1,-1]:
            for sq in [1,-1]:
                s.add((sp*p,sq*q))
    return s
def rule_arr(rid,m):
    A=np.zeros((m,m),dtype=np.int64)
    for i,(a,b) in enumerate(orbs):
        if rid>>i&1:
            for p,q in orbit_pts(a,b): A[p%m,q%m]^=1
    return A
def mul(A,B):
    m=A.shape[0]
    C=np.fft.ifft2(np.fft.fft2(A)*np.fft.fft2(B)).real
    return (np.rint(C).astype(np.int64))%2
def power(A,e):
    m=A.shape[0]; R=np.zeros((m,m),dtype=np.int64); R[0,0]=1
    while e:
        if e&1: R=mul(R,A)
        A=mul(A,A); e>>=1
    return R
def confined(A,s,q=3):
    N=(2**s-1)//q
    P=power(A,N)
    return np.array_equal(P,mul(P,P))
def dil(A,n):
    m=A.shape[0]; B=np.zeros_like(A)
    for i in range(m):
        for j in range(m):
            if A[i,j]: B[(n*i)%m,(n*j)%m]^=1
    return B
def rid_from_orbits(lst):
    return sum(1<<orbs.index(o) for o in lst)
sixteen=[1112,2436,3461,4850,5972,10498,13584,13822,17056,18246,22064,25183,26883,27390,28586,28944]
if __name__=="__main__":
    for r in sixteen:
        print(r, confined(rule_arr(r,37),18), confined(rule_arr(r,61),30))

